class Product extends DataClass implements Insertable<Product> {
  final String id;
  final DateTime createdAt;

  /// Время последнего изменения. Обновлять вручную при каждом изменении!
  final DateTime updatedAt;

  /// null = запись живая. Если дата есть, запись удалена.
  final DateTime? deletedAt;
  final String name;
  final ProductKind kind;
  final String unit;

  /// Цена продажи в копейках.
  final int priceKopecks;

  /// Закупочная цена в копейках.
  final int costKopecks;

  /// Остаток в тысячных долях: 4,5 л = 4500.
  final int stockMilli;

  /// Порог «заканчивается».
  final int minStockMilli;

  /// Для масла КПП: для какой коробки оно подходит. У остальных null.
  final GearboxType? gearbox;
  const Product({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.name,
    required this.kind,
    required this.unit,
    required this.priceKopecks,
    required this.costKopecks,
    required this.stockMilli,
    required this.minStockMilli,
    this.gearbox,
  });
