    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['name'] = Variable<String>(name);
    {
      map['kind'] = Variable<String>($ProductsTable.$converterkind.toSql(kind));
    }
    map['unit'] = Variable<String>(unit);
    map['price_kopecks'] = Variable<int>(priceKopecks);
    map['cost_kopecks'] = Variable<int>(costKopecks);
    map['stock_milli'] = Variable<int>(stockMilli);
    map['min_stock_milli'] = Variable<int>(minStockMilli);
    if (!nullToAbsent || gearbox != null) {
      map['gearbox'] = Variable<String>(
        $ProductsTable.$convertergearboxn.toSql(gearbox),
      );
    }
    return map;
  }

