    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['product_id'] = Variable<String>(productId);
    map['title'] = Variable<String>(title);
    map['qty_milli'] = Variable<int>(qtyMilli);
    map['price_kopecks'] = Variable<int>(priceKopecks);
    map['cost_kopecks'] = Variable<int>(costKopecks);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  SalesCompanion toCompanion(bool nullToAbsent) {
    return SalesCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      productId: Value(productId),
      title: Value(title),
      qtyMilli: Value(qtyMilli),
      priceKopecks: Value(priceKopecks),
      costKopecks: Value(costKopecks),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

